window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e8c16ad61949ec2d"]={"versions": [{"id": "FIG-e8c16ad61949ec2d", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation der XML-Schema-Generierungsregeln im AUTOSAR-Standard (<em>AUTOSAR_TPS_XMLSchemaProductionRules</em>). Das Diagramm modelliert den Kontroll- und Datenfluss bei der Abbildung eines UML-Attributs bzw. einer Assoziation (<code>:Property</code>) ohne Aggregation (<code>aggregation = none</code>) in XML-Schema-Deskriptoren für AUTOSAR-Modelle.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Eingangsknoten (<code>:Property</code>)</strong>: Repräsentiert das zu transformierende Modellelement vom Typ Property mit ungebundener Aggregation (<code>none</code>, Referenzeigenschaft).\n</li><li><strong>Entscheidungsknoten (<code>propertyWrapper?</code>)</strong>: Prüft das Vorhandensein bzw. Erfordernis eines Wrapper-Elements anhand der Guards <code>[propertyWrapperElement]</code> und <code>[NOT propertyWrapperElement]</code> (im Diagramm typografisch als <code>[NOT propertyWrappereElement]</code> beschriftet).\n</li><li><strong>Aktionsknoten <code>[XMLSPR0017] Create reference property (1)</code></strong>: Regelbasierte Erzeugung einer Referenzeigenschaft mit Wrapper-Element.\n</li><li><strong>Aktionsknoten <code>[XMLSPR0018] Create reference property (0)</code></strong>: Regelbasierte Erzeugung einer Referenzeigenschaft ohne Wrapper-Element.\n</li><li><strong>Merge-Knoten (Raute)</strong>: Führt die beiden alternativen Verzweigungen zusammen.\n</li><li><strong>Endknoten (<code>ActivityFinal</code>)</strong>: Schließt den Transformationsablauf für das Property-Element ab.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Ablauf beginnt mit der Übergabe der Instanz <code>:Property</code> an die Aktivität.\n</li><li>Am Verzweigungsknoten <code>propertyWrapper?</code> wird ausgewertet, ob ein umschließendes XML-Element generiert werden muss.\n</li><li>Ergibt die Bedingung <code>[propertyWrapperElement]</code> wahr, wird die Aktion <code>[XMLSPR0017] Create reference property (1)</code> ausgeführt, welche die Referenzeigenschaft inklusive Wrapper erzeugt.\n</li><li>Gilt <code>[NOT propertyWrappereElement]</code>, wird die Aktion <code>[XMLSPR0018] Create reference property (0)</code> ausgeführt, welche die Referenzeigenschaft unmittelbar ohne Wrapper generiert.\n</li><li>Beide Ausführungspfade vereinigen sich im nachfolgenden Merge-Knoten und terminieren am Endknoten <code>ActivityFinal</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Das Diagramm steuert verbindlich die XML-Schema-Repräsentation von Modellreferenzen ohne Aggregation gemäß AUTOSAR-Transformationsvorschriften.\n</li><li>Entwickler von Schema-Generatoren und Tooling-Autoren müssen anhand der Spezifikationsregeln <code>XMLSPR0017</code> bzw. <code>XMLSPR0018</code> sicherstellen, dass Referenzen abhängig vom Wrapper-Status im Metamodell syntaktisch korrekt als XML-Elementstrukturen abgebildet werden.\n</li></ul>"}, {"id": "FIG-b434c2c0bafd14cb", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation der XML-Schema-Generierungsregeln im AUTOSAR-Standard (<em>AUTOSAR_TPS_XMLSchemaProductionRules</em>). Das Diagramm modelliert den Kontroll- und Datenfluss bei der Abbildung eines UML-Attributs bzw. einer Assoziation (<code>:Property</code>) ohne Aggregation (<code>aggregation = none</code>) in XML-Schema-Deskriptoren für AUTOSAR-Modelle.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Eingangsknoten (<code>:Property</code>)</strong>: Repräsentiert das zu transformierende Modellelement vom Typ Property mit ungebundener Aggregation (<code>none</code>, Referenzeigenschaft).\n</li><li><strong>Entscheidungsknoten (<code>propertyWrapper?</code>)</strong>: Prüft das Vorhandensein bzw. Erfordernis eines Wrapper-Elements anhand der Guards <code>[propertyWrapperElement]</code> und <code>[NOT propertyWrapperElement]</code> (im Diagramm typografisch als <code>[NOT propertyWrappereElement]</code> beschriftet).\n</li><li><strong>Aktionsknoten <code>[TPS_XMLSPR_00017] Create reference property (1)</code></strong>: Regelbasierte Erzeugung einer Referenzeigenschaft mit Wrapper-Element.\n</li><li><strong>Aktionsknoten <code>[TPS_XMLSPR_00018] Create reference property (0)</code></strong>: Regelbasierte Erzeugung einer Referenzeigenschaft ohne Wrapper-Element.\n</li><li><strong>Merge-Knoten (Raute)</strong>: Führt die beiden alternativen Verzweigungen zusammen.\n</li><li><strong>Endknoten (<code>ActivityFinal</code>)</strong>: Schließt den Transformationsablauf für das Property-Element ab.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Ablauf beginnt mit der Übergabe der Instanz <code>:Property</code> an die Aktivität.\n</li><li>Am Verzweigungsknoten <code>propertyWrapper?</code> wird ausgewertet, ob ein umschließendes XML-Element generiert werden muss.\n</li><li>Ergibt die Bedingung <code>[propertyWrapperElement]</code> wahr, wird die Aktion <code>[TPS_XMLSPR_00017] Create reference property (1)</code> ausgeführt, welche die Referenzeigenschaft inklusive Wrapper erzeugt.\n</li><li>Gilt <code>[NOT propertyWrappereElement]</code>, wird die Aktion <code>[TPS_XMLSPR_00018] Create reference property (0)</code> ausgeführt, welche die Referenzeigenschaft unmittelbar ohne Wrapper generiert.\n</li><li>Beide Ausführungspfade vereinigen sich im nachfolgenden Merge-Knoten und terminieren am Endknoten <code>ActivityFinal</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Das Diagramm steuert verbindlich die XML-Schema-Repräsentation von Modellreferenzen ohne Aggregation gemäß AUTOSAR-Transformationsvorschriften.\n</li><li>Entwickler von Schema-Generatoren und Tooling-Autoren müssen anhand der Spezifikationsregeln <code>TPS_XMLSPR_00017</code> bzw. <code>TPS_XMLSPR_00018</code> sicherstellen, dass Referenzen abhängig vom Wrapper-Status im Metamodell syntaktisch korrekt als XML-Elementstrukturen abgebildet werden.\n</li></ul>"}, {"id": "FIG-3552f6a72f4e2828", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation der XML-Schema-Generierungsregeln im AUTOSAR-Standard (<em>AUTOSAR_TPS_XMLSchemaProductionRules</em>). Das Diagramm modelliert den Kontroll- und Datenfluss bei der Abbildung eines UML-Attributs bzw. einer Assoziation (<code>:Property</code>) ohne Aggregation (<code>aggregation = none</code>) in XML-Schema-Deskriptoren für AUTOSAR-Modelle.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Eingangsknoten (<code>:Property</code>)</strong>: Repräsentiert das zu transformierende Modellelement vom Typ Property mit ungebundener Aggregation (<code>none</code>, Referenzeigenschaft).\n</li><li><strong>Entscheidungsknoten (<code>propertyWrapper?</code>)</strong>: Prüft das Vorhandensein bzw. Erfordernis eines Wrapper-Elements anhand der Guards <code>[propertyWrapperElement]</code> und <code>[NOT propertyWrapperElement]</code> (im Diagramm typografisch als <code>[NOT propertyWrappereElement]</code> beschriftet).\n</li><li><strong>Aktionsknoten <code>[TPS_XMLSPR_00017] Create reference property (1)</code></strong>: Regelbasierte Erzeugung einer Referenzeigenschaft mit Wrapper-Element.\n</li><li><strong>Aktionsknoten <code>[TPS_XMLSPR_00018] Create reference property (0)</code></strong>: Regelbasierte Erzeugung einer Referenzeigenschaft ohne Wrapper-Element.\n</li><li><strong>Merge-Knoten (Raute)</strong>: Führt die beiden alternativen Verzweigungen zusammen.\n</li><li><strong>Endknoten (<code>ActivityFinal</code>)</strong>: Schließt den Transformationsablauf für das Property-Element ab.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Ablauf beginnt mit der Übergabe der Instanz <code>:Property</code> an die Aktivität.\n</li><li>Am Verzweigungsknoten <code>propertyWrapper?</code> wird ausgewertet, ob ein umschließendes XML-Element generiert werden muss.\n</li><li>Ergibt die Bedingung <code>[propertyWrapperElement]</code> wahr, wird die Aktion <code>[TPS_XMLSPR_00017] Create reference property (1)</code> ausgeführt, welche die Referenzeigenschaft inklusive Wrapper erzeugt.\n</li><li>Gilt <code>[NOT propertyWrappereElement]</code>, wird die Aktion <code>[TPS_XMLSPR_00018] Create reference property (0)</code> ausgeführt, welche die Referenzeigenschaft unmittelbar ohne Wrapper generiert.\n</li><li>Beide Ausführungspfade vereinigen sich im nachfolgenden Merge-Knoten und terminieren am Endknoten <code>ActivityFinal</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Das Diagramm steuert verbindlich die XML-Schema-Repräsentation von Modellreferenzen ohne Aggregation gemäß AUTOSAR-Transformationsvorschriften.\n</li><li>Entwickler von Schema-Generatoren und Tooling-Autoren müssen anhand der Spezifikationsregeln <code>TPS_XMLSPR_00017</code> bzw. <code>TPS_XMLSPR_00018</code> sicherstellen, dass Referenzen abhängig vom Wrapper-Status im Metamodell syntaktisch korrekt als XML-Elementstrukturen abgebildet werden.\n</li></ul>"}], "trans": [{"from": "FIG-e8c16ad61949ec2d", "to": "FIG-b434c2c0bafd14cb", "fr": "R19-11", "tr": "R20-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><strong>Aktionsknoten links</strong>: Anforderungs-Tag von <code>[XMLSPR0017] Create reference property (1)</code> in <code>[TPS_XMLSPR_00017] Create reference property (1)</code> umbenannt.\n</li><li><strong>Aktionsknoten rechts</strong>: Anforderungs-Tag von <code>[XMLSPR0018] Create reference property (0)</code> in <code>[TPS_XMLSPR_00018] Create reference property (0)</code> umbenannt.\n</li><li><strong>Farbgebung</strong>: Eingangsobjektknoten <code>:Property</code> nun bläulich statt beige hinterlegt, Verzweigungs- und Zusammenführungsknoten grünlich statt beige hinterlegt.\n</li></ul>"}, {"from": "FIG-b434c2c0bafd14cb", "to": "FIG-3552f6a72f4e2828", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
